        $scope.getParticularSigMedicationitems = function (text, item) {
            var MedicineId = null;
            item.MedicineId = item.MedicineId || null;
            if (item.MedicineId != null) {
                MedicineId = item.MedicineId;
            } else {
                MedicineId = item.MedicationId;
            }
                var params = {
                    "MedicineId": MedicineId,
                    "OrganizationId": $scope.HospitalId,
                    "SearchText": text || '',
                    "IsFrequent": "N",
                    "PageSize": 10,
                    "PageNumber": 1
                };
                if (text != "") {
                    params.IsFrequent = "N";
                }
                return eHnotePatientDataService.GetOrganizationMedicationSigList(params).then(function (resp) {
                    if (resp.data.rows.length !== 0) {
                        if (resp.data.rows !== undefined) {
                            return resp.data.rows.map(function (item) {
                                return item;
                            });
                        }
                    }

                });
        };
        $scope.getOrganizationMedicationSigitems = function (text) {
            text = text || '';
            var params = {
                "OrganizationId": $scope.HospitalId,
                "SearchText": text || '',
                "IsFrequent": "Y",
                "PageSize": 10,
                "PageNumber": 1

            };
            if (text != "") {
                params.IsFrequent = "N";
            }
            return eHnotePatientDataService.GetOrganizationMedicationSigList(params).then(function (resp) {
                if (resp.data.rows.length !== 0) {
                    if (resp.data.rows !== undefined) {
                        return resp.data.rows.map(function (item) {
                            return item;
                        });
                    }
                }

            });

        };
